void FightScreenRound_drawFade(FightScreenRound* ro) {
    if (Fade_isActive(ro->fadeOut)) {
        Fade_draw(ro->fadeOut);
    } else {
        if (Fade_isActive(ro->fadeIn)) {
            Fade_draw(ro->fadeIn);
        } else {
            if (g_sys.clsnDisplay && g_sys.cfg.Debug.ClsnDarken) {
                Fade_drawRect(ro->fadeIn, g_sys.SystemStateVars_.scrrect, 0U, 0);
            }
        }
    }
    if (ro->shutterTimer > 0) {
        Arr4_i32 rect = g_sys.SystemStateVars_.scrrect;
        i32 half = (i32)((((g_sys.SystemStateVars_.scrrect.v[3] + 1))) >> 1);
        i32 cover = 0;
        if (ro->shutter_time > 0) {
            if (ro->shutterTimer > ro->shutter_time) {
                i32 t = ((ro->shutter_time * 2) - ro->shutterTimer);
                if (t < 0) {
                    t = 0;
                }
                if (t > ro->shutter_time) {
                    t = ro->shutter_time;
                }
                cover = go_div32((t * half), ro->shutter_time);
            } else {
                i32 t = ro->shutterTimer;
                if (t < 0) {
                    t = 0;
                }
                if (t > ro->shutter_time) {
                    t = ro->shutter_time;
                }
                cover = go_div32((t * half), ro->shutter_time);
            }
        }
        rect.v[3] = cover;
        Fade_drawRect(ro->fadeIn, rect, ro->shutter_col, 255);
        rect.v[1] = (g_sys.SystemStateVars_.scrrect.v[3] - rect.v[3]);
        Fade_drawRect(ro->fadeIn, rect, ro->shutter_col, 255);
    }
}

